import org.junit.Test;
import static org.junit.Assert.*;
import org.mockito.Mockito;

public class GalileoProtocolDecoderTest {

    @Test
    public void constructor_GalileoProtocolDecoderShouldBeCreatedWithCorrectProtocol() {
        Protocol protocol = Mockito.mock(Protocol.class);
        assertEquals(protocol, new GalileoProtocolDecoder(protocol).getProtocol());
    }

    @Test
    public void decode_ChannelShouldNotBeNullWhenDecodeMethodIsCalled() {
        Channel channel = new Channel();
        SocketAddress remoteAddress = new SocketAddress();
        Object msg = new Object();

        GalileoProtocolDecoder decoder = new GalileoProtocolDecoder(new Protocol());
        Object decodedMsg = decoder.decode(channel, remoteAddress, msg);

        assertNotNull(decodedMsg);
    }

    @Test
    public void decode_WithEmptyMessageShouldReturnEmptyString() {
        Channel channel = new Channel();
        SocketAddress remoteAddress = new SocketAddress();
        Object msg = "";

        GalileoProtocolDecoder decoder = new GalileoProtocolDecoder(new Protocol());
        String decodedMsg = decoder.decode(channel, remoteAddress, msg).toString();

        assertEquals("", decodedMsg);
    }

    @Test
    public void decode_WithNullMessageShouldThrowException() {
        Channel channel = new Channel();
        SocketAddress remoteAddress = new SocketAddress();
        Object msg = null;

        GalileoProtocolDecoder decoder = new GalileoProtocolDecoder(new Protocol());
        assertThrows(Exception.class, () -> decoder.decode(channel, remoteAddress, msg));
    }

    @Test
    public void decode_WithNullChannelShouldThrowException() {
        Channel channel = null;
        SocketAddress remoteAddress = new SocketAddress();
        Object msg = new Object();

        GalileoProtocolDecoder decoder = new GalileoProtocolDecoder(new Protocol());
        assertThrows(Exception.class, () -> decoder.decode(channel, remoteAddress, msg));
    }

    @Test
    public void decode_WithNullRemoteAddressShouldThrowException() {
        Channel channel = new Channel();
        SocketAddress remoteAddress = null;
        Object msg = new Object();

        GalileoProtocolDecoder decoder = new GalileoProtocolDecoder(new Protocol());
        assertThrows(Exception.class, () -> decoder.decode(channel, remoteAddress, msg));
    }

}

